// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        // Ensure player is not the zero address and is a real person (tx.origin == msg.sender)
        vm.assume(player != address(0) && player != address(this));

        // Set up: open to public, set bet limit, give player ether, and make them wager
        c.OpenToThePublic();
        c.AdjustBetAmounts(1 ether);
        vm.deal(player, 1 ether);

        vm.prank(player, player);
        c.wager{value: 1 ether}();

        // Now call AdjustBetAmounts (boundary function) - doesn't affect the wager mapping
        c.AdjustBetAmounts(2 ether);

        // The rule: player has wagered, so hasPlayerWagered must return true
        assertTrue(c.hasPlayerWagered(player));
    }
}

